async page => {
 const checks=[], errors=[]; page.on('pageerror',e=>errors.push(e.message));
 const assert=(condition,message)=>{if(!condition)throw Error(message); checks.push(message)};
 await page.goto('http://127.0.0.1:5181');
 await page.getByRole('button',{name:'Português (Brasil)',exact:true}).click();
 await page.locator('#schedule-date').fill('');
 await page.locator('.hd-schedule-submit').click();
 assert(await page.getByRole('alert').count()===1,'Data vazia rejeitada');
 await page.locator('#schedule-date').fill('2026-11-18');
 await page.locator('.hd-schedule-submit').click();
 assert(await page.getByRole('alert').count()===1,'Horário vazio rejeitado');
 await page.getByRole('button',{name:'09:00',exact:true}).click();
 await page.locator('#schedule-client').fill('   ');
 await page.locator('.hd-schedule-submit').click();
 assert(await page.getByRole('alert').count()===1 && await page.locator('.hd-appointment-row').count()===0,'Nome em branco rejeitado');
 for(const [name,time] of [['Teste Noite','21:00'],['Teste Manhã B','12:00'],['Teste Tarde','13:00'],['Teste Manhã A','09:00']]) {
  await page.getByRole('button',{name:time,exact:true}).click(); await page.locator('#schedule-client').fill(name); await page.locator('.hd-schedule-submit').click();
 }
 assert(await page.locator('#agenda-date').inputValue()==='2026-11-18','Cadastro seleciona a data agendada');
 assert(JSON.stringify(await page.locator('.hd-appointment-row time').allTextContents())===JSON.stringify(['09:00','12:00','13:00','21:00']),'Cadastro imediato e ordem cronológica');
 for(const [period,n] of [['morning',2],['afternoon',1],['night',1]]) assert(await page.locator('[data-period='+period+'] .hd-appointment-row').count()===n,'Período '+period+' correto');
 await page.locator('#agenda-date').fill('2026-11-19');
 assert(await page.locator('.hd-appointment-row').count()===0,'Filtro por data');
 const empty=await page.locator('.hd-period-empty').allTextContents();
 assert(empty.length===3 && empty.every(x=>x==='Você ainda não tem agendamentos cadastrados nesse período.'),'Mensagem vazia exata nos três períodos');
 await page.locator('#agenda-date').fill('2026-11-18');
 return {checks,errors};
 }

